void source_run_recorded_animation_tu15(M &m,std::uint32_t entry,
    SourcePhysicsContactRuntimeAbi &abi,FP fp,
    const SourcePhysicsContactRuntimeServices &services,const O &observe) {
    constexpr auto image=SourcePhysicsContactImage::TitleUpdate15;
    FpScope scope(fp);LiveState s{m,observe,services,image};s.load(abi);
    try {
        switch(entry) {
case 0x127210u:run_127210(s);break;
case 0x166a80u:run_166a80(s);break;
case 0x166ae0u:run_166ae0(s);break;
case 0x16e450u:run_16e450(s);break;
case 0x16e4b0u:run_16e4b0(s);break;
case 0x16e600u:run_16e600(s);break;
case 0x2035b0u:run_2035b0(s);break;
case 0x2035f0u:run_2035f0(s);break;
case 0x203610u:run_203610(s);break;
case 0x2039b0u:run_2039b0(s);break;
case 0x32a4e0u:run_32a4e0(s);break;

        default:throw std::runtime_error("Required original contact entry unavailable");
        }
    } catch(...) {abi=s.save();throw;}
    abi=s.save();
}
bool source_recorded_animation_tu15_owns_entry(std::uint32_t p) {return p==0x2035b0u || p==0x2035f0u || p==0x203610u || p==0x2039b0u;}
